function drawArrow(x1, y1, x2, y2, color, width) {
  var dx = x2 - x1, dy = y2 - y1;
  var L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L;
  var head = 25, wing = 15;
  var ex = x2 - ux * head * 0.65, ey = y2 - uy * head * 0.65;
  draw.line(x1, y1, ex, ey).stroke({ color: color, width: width, linecap: 'butt' });
  var px = -uy, py = ux;
  draw.polygon([
    [x2, y2],
    [x2 - ux * head + px * wing, y2 - uy * head + py * wing],
    [x2 - ux * head - px * wing, y2 - uy * head - py * wing]
  ]).fill(color).stroke('none');
}

function boxDataFor(level, index, frame) {
