  var len = canonical[level][index].length;
  var data = boxDataFor(level, index, frame);
  var elems = data.elems || [];
  var g = draw.group();
  var fill = data.faint ? '#eeeeee' : '#d9d9d9';
  var rect = g.rect(b.w, b.h).move(b.x, b.y).fill(fill).stroke({ color: opts.active ? '#f28e2b' : '#111', width: opts.active ? 4 : 1.6 });
  if (opts.dest) rect.stroke({ color: '#2f80ed', width: 4 });
  if (opts.bad) rect.stroke({ color: '#d62728', width: 5 });
  g.opacity(data.faint ? 0.32 : 1);
  for (var i = 0; i < len; i++) {
    var cx = b.x + (i + 0.5) * b.w / len;
    var cy = b.y + b.h / 2 + 11;
    if (opts.comparePos === i) {
      g.circle(Math.min(38, b.w / len * 0.78)).center(cx, b.y + b.h / 2).fill('#ffe08a').stroke({ color: '#c47f00', width: 2 });
    }
    if (opts.outputPos === i) {
      g.rect(Math.max(22, b.w / len * 0.75), b.h - 8).center(cx, b.y + b.h / 2).fill('#b8f2c6').stroke({ color: '#219653', width: 2 });
    }
    if (elems[i]) {
      g.text(String(elems[i].v)).font({ family: 'serif', size: level === 0 ? 31 : 34, anchor: 'middle' }).center(cx, cy - 3).fill('#000');
      if (stableTrace && elems[i].v === 2) {
        var badge = elems[i].id === 1 ? { c: '#2f80ed', t: 'A' } : (elems[i].id === 6 ? { c: '#9b51e0', t: 'B' } : null);
        if (badge) {
          g.circle(16).center(cx + Math.min(20, b.w / len * 0.27), b.y + 10).fill(badge.c).stroke({ color: '#fff', width: 1.5 });
          g.text(badge.t).font({ family: 'sans-serif', size: 10, weight: 'bold', anchor: 'middle' }).center(cx + Math.min(20, b.w / len * 0.27), b.y + 13).fill('#fff');
