  if (!active || active.level == null) return null;
  for (var i = 0; i < merges.length; i++) {
    if (merges[i].level === active.level && merges[i].dest === active.dest) return merges[i];
  }
  return null;
}

function drawStaticLabels() {
  draw.text('sorted sequence').font({ family: 'serif', size: 30, anchor: 'middle' }).center(560, 23).fill('#000');
  draw.text('initial sequence').font({ family: 'serif', size: 30, anchor: 'middle' }).center(560, 675).fill('#000');
}

function renderFigure(frame) {
  draw.clear();
  draw.rect(1100, 700).fill('#fff');
  var active = replayMode && frame ? frame.active : callMap[callTrace];
  var mActive = mergeForActive(active);

  merges.forEach(function (m) {
    var lb = boxes[m.left[0]][m.left[1]], rb = boxes[m.right[0]][m.right[1]], db = boxes[m.level][m.dest];
    var lActive = mActive && m.level === mActive.level && m.dest === mActive.dest;
    var color = lActive ? '#f28e2b' : '#808080';
    var width = lActive ? 8 : 6;
    drawArrow(lb.x + lb.w / 2, lb.y - 20, db.x + db.w * 0.35, db.y + db.h + 22, color, width);
    drawArrow(rb.x + rb.w / 2, rb.y - 20, db.x + db.w * 0.65, db.y + db.h + 22, color, width);
    var label = draw.text('merge').font({ family: 'serif', size: 32, anchor: 'middle' }).center(m.label[0], m.label[1]).fill('#000');
    label.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
    label.on('mousemove', function (e) {
      showTooltip('merge compares the two front elements and appends the smaller one.', e);
    }).on('mouseleave', hideTooltip).css('cursor', 'pointer');
  });

  var compareMap = {};
  var outputMap = {};
  var badMap = {};
  if (frame && frame.indices) {
    if (frame.indices.left) compareMap[frame.indices.left.level + ':' + frame.indices.left.index] = frame.indices.left.pos;
    if (frame.indices.right) compareMap[frame.indices.right.level + ':' + frame.indices.right.index] = frame.indices.right.pos;
    if (frame.indices.output) outputMap[frame.indices.output.level + ':' + frame.indices.output.index] = frame.indices.output.pos;
    if (frame.indices.bad) frame.indices.bad.forEach(function (b) { badMap[b.level + ':' + b.index] = true; });
  }

  for (var l = 3; l >= 0; l--) {
    for (var i = 0; i < boxes[l].length; i++) {
      var k = l + ':' + i;
      var isActive = false, isDest = false;
      if (active) {
        isActive = k === activeKey(active.left) || k === activeKey(active.right);
        isDest = k === destinationKey(active);
        if (callTrace === 'initial' && l === 0) isActive = true;
      }
      drawRunBox(l, i, {
        active: isActive,
        dest: isDest,
        comparePos: compareMap[k],
        outputPos: outputMap[k],
        bad: badMap[k]
      }, frame);
    }
  }
  drawStaticLabels();
}

function setMergeCallTrace(v) {
  replayMode = false;
  stopPlay();
  callTrace = v;
  renderFigure(null);
}

function toggle_stableMergeTrace(on) {
  stableTrace = !!on;
  renderCurrent();
}

function loadCodeSample(which) {
  var t = document.getElementById('mergeRoutineCode');
  t.value = which === 'buggy' ? buggyCode : (which === 'starter' ? starterCode : sampleCode);
}

function workerSource() {
  return `
self.onmessage = function(ev) {
  var code = ev.data.code, input = ev.data.input;
  var frames = [], opCount = 0, frameCap = 500, opCap = 300;
  function cp(x){ return JSON.parse(JSON.stringify(x)); }
  function elem(v,i){ return {v:v,id:i}; }
  function parseInput(s){
    var parts = String(s).split(',').map(function(x){ return x.trim(); }).filter(Boolean);
    if (parts.length !== 8) throw new Error('Use exactly 8 comma-separated numbers for this lattice.');
    return parts.map(function(p,i){ var n = Number(p); if(!isFinite(n)) throw new Error('Not a number: '+p); return elem(n,i); });
  }
  var initial, levels, runs, active, leftRun, rightRun, out, li, ri;
  function snapshot(kind, indices, message){
    opCount++;
    if (opCount > opCap) throw new Error('operation cap hit; check for an infinite loop');
    if (frames.length >= frameCap) throw new Error('frame cap hit; the trace is too long');
    frames.push({kind:kind, state:{levels:cp(levels)}, active:cp(active), indices:cp(indices||{}), message:String(message||'')});
  }
  function hasLeft(){ snapshot('hasLeft',{left:{level:active.left.level,index:active.left.index,pos:li}}, 'hasLeft() → '+(li<leftRun.length)); return li < leftRun.length; }
  function hasRight(){ snapshot('hasRight',{right:{level:active.right.level,index:active.right.index,pos:ri}}, 'hasRight() → '+(ri<rightRun.length)); return ri < rightRun.length; }
  function compareFront(){
    if (li >= leftRun.length || ri >= rightRun.length) throw new Error('compareFront() called when one run is empty');
    var a = leftRun[li], b = rightRun[ri], c = a.v < b.v ? -1 : (a.v > b.v ? 1 : 0);
    snapshot('compare', {
      left:{level:active.left.level,index:active.left.index,pos:li},
      right:{level:active.right.level,index:active.right.index,pos:ri}
    }, 'compareFront(): '+a.v+' vs '+b.v+' → '+c);
    return c;
  }
  function appendLeft(){
    if (li >= leftRun.length) throw new Error('appendLeft() called with no left front element');
    out.push({v:leftRun[li].v,id:leftRun[li].id}); li++;
    levels[active.level][active.dest] = cp(out);
    snapshot('appendLeft', {output:{level:active.level,index:active.dest,pos:out.length-1}}, 'appendLeft(): output now ['+out.map(function(e){return e.v}).join(', ')+']');
  }
  function appendRight(){
    if (ri >= rightRun.length) throw new Error('appendRight() called with no right front element');
    out.push({v:rightRun[ri].v,id:rightRun[ri].id}); ri++;
    levels[active.level][active.dest] = cp(out);
    snapshot('appendRight', {output:{level:active.level,index:active.dest,pos:out.length-1}}, 'appendRight(): output now ['+out.map(function(e){return e.v}).join(', ')+']');
  }
  function note(text){ snapshot('note', {}, String(text)); }
  self.hasLeft = hasLeft; self.hasRight = hasRight; self.compareFront = compareFront;
  self.appendLeft = appendLeft; self.appendRight = appendRight; self.note = note;
  Object.freeze(self.hasLeft); Object.freeze(self.hasRight); Object.freeze(self.compareFront);
  try {
    initial = parseInput(input);
    levels = [initial.map(function(e){return [e];}), [], [], []];
    runs = levels[0].map(cp);
    frames.push({kind:'start', state:{levels:cp(levels)}, active:null, indices:{}, message:'Start with eight single-element sorted runs.'});
    var mergeFn = (new Function(code + '\\n; return (typeof merge === "function") ? merge : null;'))();
    if (!mergeFn) throw new Error('Define the required entry point: function merge(left, right) { ... }');
    for (var lev=1; runs.length > 1; lev++) {
      var next = [];
      levels[lev] = [];
      for (var p=0; p<runs.length; p+=2) {
        leftRun = cp(runs[p]); rightRun = cp(runs[p+1]); out = []; li = 0; ri = 0;
        active = {level:lev,dest:p/2,left:{level:lev-1,index:p},right:{level:lev-1,index:p+1}};
        levels[lev][p/2] = [];
        snapshot('activate', {}, 'Merge ['+leftRun.map(function(e){return e.v}).join(', ')+'] with ['+rightRun.map(function(e){return e.v}).join(', ')+']');
        mergeFn(Object.freeze(leftRun.map(function(e){return e.v;})), Object.freeze(rightRun.map(function(e){return e.v;})));
        levels[lev][p/2] = cp(out);
        next.push(cp(out));
      }
      runs = next;
    }
    var final = runs[0] || [];
    var bad = [];
    for (var i=1;i<final.length;i++) if (final[i-1].v > final[i].v || (final[i-1].v === final[i].v && final[i-1].id > final[i].id)) bad.push(i-1,i);
    var ids = final.map(function(e){return e.id}).sort(function(a,b){return a-b}).join(',');
    var okSet = ids === initial.map(function(e){return e.id}).sort(function(a,b){return a-b}).join(',');
    var ok = bad.length === 0 && okSet && final.length === initial.length;
    frames.push({kind: ok?'correct':'wrong', state:{levels:cp(levels)}, active:{level:3,dest:0}, indices: ok?{}:{bad:[{level:3,index:0}]}, message: ok ? 'Correct: outputs are sorted and stable; equal values keep left-before-right order.' : 'Wrong answer: the final run is not sorted, stable, or does not contain exactly the input elements.', status: ok?'correct':'wrong'});
    self.postMessage({ok:true, frames:frames, status: ok?'correct':'wrong'});
  } catch(e) {
    frames.push({kind:'error', state:{levels:cp(levels || [[]])}, active:active ? cp(active) : null, indices:{}, message:'Error: '+(e && e.message ? e.message : e), status:'error'});
    self.postMessage({ok:false, frames:frames, status:'error', error:String(e && e.message ? e.message : e)});
  }
};`;
}

function runMergeRoutine() {
  stopPlay();
  var btn = document.getElementById('runMergeBtn');
  btn.disabled = true;
  document.getElementById('mergeStatus').textContent = 'running…';
  var blob = new Blob([workerSource()], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var w = new Worker(url);
  var finished = false;
  var timer = setTimeout(function () {
    if (finished) return;
    finished = true;
    w.terminate();
    URL.revokeObjectURL(url);
    btn.disabled = false;
    traceFrames = [{ kind: 'timeout', state: { levels: canonical }, active: null, indices: {}, message: 'Error: time limit hit; check for an infinite loop.', status: 'error' }];
    frameIndex = 0;
    replayMode = true;
    document.getElementById('mergeStatus').textContent = 'error';
    renderCurrent();
  }, 1800);
  w.onmessage = function (ev) {
    if (finished) return;
    finished = true;
    clearTimeout(timer);
    w.terminate();
    URL.revokeObjectURL(url);
    btn.disabled = false;
    traceFrames = ev.data.frames || [];
    frameIndex = 0;
    replayMode = true;
    document.getElementById('mergeStatus').textContent = ev.data.status === 'correct' ? 'correct' : (ev.data.status === 'wrong' ? 'wrong answer' : 'error');
    renderCurrent();
  };
  w.postMessage({ code: document.getElementById('mergeRoutineCode').value, input: document.getElementById('mergeRoutineInput').value });
}

function renderCurrent() {
  var f = replayMode ? traceFrames[frameIndex] : null;
  renderFigure(f);
  document.getElementById('frameCounter').textContent = traceFrames.length ? ((frameIndex + 1) + ' of ' + traceFrames.length) : '0 of 0';
  document.getElementById('frameCaption').textContent = f ? f.message : 'Use the call-trace menu or run your merge routine.';
  document.getElementById('traceLog').value = traceFrames.map(function (fr, i) { return (i + 1) + '. ' + fr.message; }).join('\n');
}

function firstFrame() { if (!traceFrames.length) return; replayMode = true; frameIndex = 0; renderCurrent(); }
function prevFrame() { if (!traceFrames.length) return; replayMode = true; frameIndex = Math.max(0, frameIndex - 1); renderCurrent(); }
function nextFrame() { if (!traceFrames.length) return; replayMode = true; frameIndex = Math.min(traceFrames.length - 1, frameIndex + 1); renderCurrent(); }
function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playBtn').textContent = '▶';
}
function togglePlay() {
  if (!traceFrames.length) return;
  if (playTimer) { stopPlay(); return; }
  replayMode = true;
  document.getElementById('playBtn').textContent = '❚❚';
  var speed = +document.getElementById('speedInput').value || 4;
  playTimer = setInterval(function () {
    if (frameIndex >= traceFrames.length - 1) { stopPlay(); return; }
    frameIndex++;
    renderCurrent();
  }, Math.max(120, 950 - speed * 95));
}

function applyDemoStep() {
  var st = demoSteps[demoIndex];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
  document.getElementById('mergeCallTraceInput').value = st.state.mergeCallTrace;
  document.getElementById('stableMergeTraceInput').checked = st.state.stableMergeTrace === 'Show duplicate origins';
  callTrace = st.state.mergeCallTrace;
  stableTrace = st.state.stableMergeTrace === 'Show duplicate origins';
  replayMode = false;
  stopPlay();
  renderFigure(null);
}
function prevStep() { demoIndex = Math.max(0, demoIndex - 1); applyDemoStep(); }
function nextStep() { demoIndex = Math.min(demoSteps.length - 1, demoIndex + 1); applyDemoStep(); }

renderFigure(null);
applyDemoStep();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Merge sort builds a sorted sequence by repeatedly merging adjacent already-sorted runs, doubling run length at each level until one sorted run remains.
KEY INSIGHT (what students should walk away understanding): Merge sort succeeds because each merge assumes its two inputs are already sorted, so sorting the whole array reduces to repeatedly merging larger and larger sorted runs.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Merge sort builds a sorted sequence by repeatedly merging adjacent already-sorted runs, doubling run length at each level until one sorted run remains.",
  "figureType": "diagram",
  "elements": [
    "bottom label 'initial sequence'",
    "bottom rank of eight gray single-element boxes containing 5, 2, 4, 7, 1, 3, 2, 6 from left to right",
    "first merge level of four gray two-element boxes containing 2 5, 4 7, 1 3, and 2 6",
    "second merge level of two gray four-element boxes containing 2 4 5 7 and 1 2 3 6",
    "top gray eight-element box containing 1 2 2 3 4 5 6 7",
    "top label 'sorted sequence'",
    "thick gray upward arrows from each pair of lower boxes to its merged output box",
    "six visible 'merge' labels centered near the arrow pairs between levels",
    "active-merge highlight outline around the two input runs, their arrows, and the destination run",
    "comparison highlight on the current front elements during a merge replay",
    "output insertion highlight showing the next slot filled in the destination box",
    "optional origin badges on duplicate values, distinguishing the left duplicate 2 from the right duplicate 2 when stability trace is enabled"
  ],
  "interactions": [
    {
      "id": "mergeRoutine",
      "type": "code_editor",
      "label": "Implement merge(left, right)",
      "entry_point": "merge(left, right)",
      "api": [
        {
          "op": "hasLeft()",
          "does": "true if the active left run still has an unmerged front element"
        },
        {
          "op": "hasRight()",
          "does": "true if the active right run still has an unmerged front element"
        },
        {
          "op": "compareFront()",
          "does": "compares the current front values of the left and right runs, records the comparison frame, and returns -1, 0, or 1 for left < right, left = right, or left > right"
        },
        {
          "op": "appendLeft()",
          "does": "appends the current left front element to the output run and advances the left pointer"
        },
        {
          "op": "appendRight()",
          "does": "appends the current right front element to the output run and advances the right pointer"
        },
        {
          "op": "note(text)",
          "does": "adds a short learner note to the current replay frame without changing the data"
        }
      ],
      "frame": "the whole merge-sort lattice, with the active left and right runs, their front pointers, the compared values, and the growing destination run highlighted",
      "input": {
        "label": "Initial sequence",
        "default": "5, 2, 4, 7, 1, 3, 2, 6"
      },
      "sample_code": "function merge(left, right) {\n  while (hasLeft() && hasRight()) {\n    const cmp = compareFront();\n    if (cmp <= 0) {\n      appendLeft();\n    } else {\n      appendRight();\n    }\n  }\n\n  while (hasLeft()) {\n    appendLeft();\n  }\n\n  while (hasRight()) {\n    appendRight();\n  }\n}",
      "buggy_code": "function merge(left, right) {\n  // Bug: equal values are taken from the right run first, so the output can be sorted but not stable.\n  while (hasLeft() && hasRight()) {\n    const cmp = compareFront();\n    if (cmp < 0) {\n      appendLeft();\n    } else {\n      appendRight();\n    }\n  }\n\n  while (hasLeft()) appendLeft();\n  while (hasRight()) appendRight();\n}",
      "success_check": "each merge output is sorted, contains exactly the input elements, and preserves the relative order of equal-valued elements by taking from the left run first on ties",
      "teaches": "The learner understands that merge sort's work happens inside the merge routine: only the two front elements need to be compared, and the smaller front element is repeatedly appended to build the next sorted run"
    },
    {
      "id": "mergeCallTrace",
      "type": "state",
      "label": "Merge-sort call trace",
      "states": [
        "initial",
        "merge 5 and 2",
        "merge 4 and 7",
        "merge 1 and 3",
        "merge 2 and 6",
        "merge 2 5 with 4 7",
        "merge 1 3 with 2 6",
        "final merge",
        "done"
      ],
      "default": "initial",
      "teaches": "The learner sees the recursive merge tree build upward: sorted singletons become sorted pairs, pairs become sorted four-element runs, and the final two runs merge into the complete sorted sequence"
    },
    {
      "id": "stableMergeTrace",
      "type": "toggle",
      "label": "Stable-merge trace",
      "options": [
        "Values only",
        "Show duplicate origins"
      ],
      "default": "Values only",
      "teaches": "The learner sees that when two equal values are compared, choosing the left run first preserves their original relative order, which is the meaning of stability"
    }
  ],
  "demo_steps": [
    {
      "title": "Start with single-element sorted runs",
      "narration": "At the bottom, every single element is already sorted by itself. Merge sort begins by treating the initial sequence as eight length-one sorted runs.",
      "state": {
        "mergeCallTrace": "initial",
        "stableMergeTrace": "Values only"
      }
    },
    {
      "title": "Merge adjacent singletons",
      "narration": "Step through the first merge calls: adjacent one-element runs are compared and combined into sorted two-element runs such as 5 and 2 becoming 2 5.",
      "state": {
        "mergeCallTrace": "merge 5 and 2",
        "stableMergeTrace": "Values only"
      }
    },
    {
      "title": "Runs double in size",
      "narration": "The next level merges sorted pairs into sorted four-element runs. The boxes get wider while their count halves, making the divide-and-conquer structure visible.",
      "state": {
        "mergeCallTrace": "merge 2 5 with 4 7",
        "stableMergeTrace": "Values only"
      }
    },
    {
      "title": "Trace duplicate values",
      "narration": "Turn on the stability trace before the final merge. The two 2 values have different origins, so a stable merge keeps the left-run 2 before the right-run 2 when their values tie.",
      "state": {
        "mergeCallTrace": "final merge",
        "stableMergeTrace": "Show duplicate origins"
      }
    },
    {
      "title": "One sorted sequence remains",
      "narration": "After the final merge, all elements have been copied into the top run in sorted order. The full array is sorted because every level only merges runs that were already sorted.",
      "state": {
        "mergeCallTrace": "done",
        "stableMergeTrace": "Show duplicate origins"
      }
    }
  ],
  "keyInsight": "Merge sort succeeds because each merge assumes its two inputs are already sorted, so sorting the whole array reduces to repeatedly merging larger and larger sorted runs.",
  "reconstructionNotes": "Recreate the original bottom-up lattice on a white background with light-gray rectangular boxes outlined in black and large serif numerals. Arrange ranks vertically: eight singletons at the bottom, four pairs above, two four-element runs above that, and one long sorted run at the top. Use thick gray upward arrows in pairs from child runs to parent runs, with the word 'merge' near each arrow pair. Box width should scale with run length so the visual doubling of run size is obvious. Highlights should use a contrasting color such as blue or orange without obscuring the original gray boxes; duplicate-origin badges for the two 2s should be small colored markers that appear only in stable-trace mode."
}

