function destinationKey(a) {
  return a ? (a.level + ':' + a.dest) : '';
}

function drawArrow(x1, y1, x2, y2, color, width, interactiveText) {
  var dx = x2 - x1, dy = y2 - y1;
  var L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L;
  var head = 56, wing = 31;
  var ex = x2 - ux * head * 0.72, ey = y2 - uy * head * 0.72;
  var g = draw.group();
  g.line(x1, y1, ex, ey).stroke({ color: color, width: width, linecap: 'butt' });
  var px = -uy, py = ux;
  g.polygon([
    [x2, y2],
    [x2 - ux * head + px * wing, y2 - uy * head + py * wing],
    [x2 - ux * head - px * wing, y2 - uy * head - py * wing]
  ]).fill(color).stroke('none');
  if (interactiveText) {
    g.on('mousemove', function (e) { showTooltip(interactiveText, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Merge arrow', 'The arrow points from an already-sorted input run up to the larger run produced by merging it with its neighbor.');
      })
      .css('cursor', 'pointer');
  }
  return g;
}

function mergeForActive(active) {
  if (!active || active.level == null || active.left == null || active.right == null) return null;
  for (var i = 0; i < merges.length; i++) {
    if (merges[i].level === active.level && merges[i].dest === active.dest) return merges[i];
  }
  return null;
}

function boxDataFor(level, index, frame) {
  if (replayMode && frame && frame.state && frame.state.levels) {
    var lev = frame.state.levels[level];
    if (lev && typeof lev[index] !== 'undefined') return { elems: lev[index], faint: false };
    return { elems: canonical[level][index], faint: true };
  }
  return { elems: canonical[level][index], faint: false };
}

function drawRunBox(level, index, opts, frame) {
  opts = opts || {};
  var b = boxes[level][index];
  var len = canonical[level][index].length;
  var data = boxDataFor(level, index, frame);
  var elems = data.elems || [];
  var g = draw.group();
  var rect = g.rect(b.w, b.h).move(b.x, b.y).fill('#d9d9d9').stroke({ color: '#111', width: 2.2 });
  if (opts.active) rect.stroke({ color: '#f28e2b', width: 7 });
  if (opts.dest) rect.stroke({ color: '#2f80ed', width: 7 });
  if (opts.bad) rect.stroke({ color: '#d62728', width: 8 });
  g.opacity(data.faint ? 0.28 : 1);

  for (var i = 0; i < len; i++) {
    var cx = b.x + (i + 0.5) * b.w / len;
    var cy = b.y + b.h / 2;
    if (opts.comparePos === i) {
      g.circle(Math.min(56, b.w / len * 0.78)).center(cx, cy).fill('#ffe08a').stroke({ color: '#c47f00', width: 3 });
    }
    if (opts.outputPos === i) {
      g.rect(Math.max(35, b.w / len * 0.76), b.h - 12).center(cx, cy).fill('#b8f2c6').stroke({ color: '#219653', width: 3 });
    }
    if (elems[i]) {
      g.text(String(elems[i].v)).font({ family: 'serif', size: level === 0 ? 47 : 48, anchor: 'middle' }).center(cx, cy + 7).fill('#000');
      if (stableTrace && elems[i].v === 2) {
        var badge = elems[i].id === 1 ? { c: '#2f80ed', t: 'A' } : (elems[i].id === 6 ? { c: '#9b51e0', t: 'B' } : null);
        if (badge) {
          var bx = cx + Math.min(30, b.w / len * 0.28);
          g.circle(22).center(bx, b.y + 14).fill(badge.c).stroke({ color: '#fff', width: 2 });
          g.text(badge.t).font({ family: 'sans-serif', size: 14, weight: 'bold', anchor: 'middle' }).center(bx, b.y + 18).fill('#fff');
        }
      }
    }
  }

  g.on('mousemove', function (e) {
    showTooltip('A sorted run of length ' + len + '. Merge sort combines adjacent sorted runs to make the next level.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('Already-sorted run', 'Every box represents a run that is sorted before it is used as input to the next merge. That invariant is why the algorithm can build the final sorted sequence one level at a time.');
  }).css('cursor', 'pointer');
}

function drawStaticLabels() {
  draw.text('sorted sequence').font({ family: 'serif', size: 52, anchor: 'middle' }).center(870, 32).fill('#000');
  draw.text('initial sequence').font({ family: 'serif', size: 52, anchor: 'middle' }).center(870, 1077).fill('#000');
}

function renderFigure(frame) {
  draw.clear();
  draw.rect(1740, 1122).fill('#fff');

  var active = replayMode && frame ? frame.active : callMap[callTrace];
  var mActive = mergeForActive(active);

  merges.forEach(function (m) {
    var lb = boxes[m.left[0]][m.left[1]], rb = boxes[m.right[0]][m.right[1]], db = boxes[m.level][m.dest];
    var lActive = mActive && m.level === mActive.level && m.dest === mActive.dest;
    var color = lActive ? '#f28e2b' : '#808080';
    var width = lActive ? 12 : 9;

    drawArrow(lb.x + lb.w / 2, lb.y - 33, db.x + db.w * 0.36, db.y + db.h + 34, color, width, 'This input run is merged with its neighbor.');
    drawArrow(rb.x + rb.w / 2, rb.y - 33, db.x + db.w * 0.64, db.y + db.h + 34, color, width, 'This input run is merged with its neighbor.');

    var label = draw.text('merge').font({ family: 'serif', size: 48, anchor: 'middle' }).center(m.label[0], m.label[1]).fill('#000');
    label.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 8, 'stroke-linejoin': 'round' });
    label.on('mousemove', function (e) {
      showTooltip('merge compares the two front elements and appends the smaller one to the output run.', e);
    }).on('mouseleave', hideTooltip).on('click', function () {
      showPopup('Merge operation', 'A merge assumes both input runs are already sorted. It repeatedly compares only the two front elements, appending the smaller front element until one larger sorted run is complete.');
    }).css('cursor', 'pointer');
  });

  var compareMap = {};
  var outputMap = {};
  var badMap = {};
  if (frame && frame.indices) {
    if (frame.indices.left) compareMap[frame.indices.left.level + ':' + frame.indices.left.index] = frame.indices.left.pos;
    if (frame.indices.right) compareMap[frame.indices.right.level + ':' + frame.indices.right.index] = frame.indices.right.pos;
    if (frame.indices.output) outputMap[frame.indices.output.level + ':' + frame.indices.output.index] = frame.indices.output.pos;
    if (frame.indices.bad) frame.indices.bad.forEach(function (b) { badMap[b.level + ':' + b.index] = true; });
  }

  for (var l = 3; l >= 0; l--) {
    for (var i = 0; i < boxes[l].length; i++) {
      var k = l + ':' + i;
      var isActive = false, isDest = false;
      if (active && callTrace !== 'initial') {
        isActive = k === activeKey(active.left) || k === activeKey(active.right);
        isDest = k === destinationKey(active);
      }
      drawRunBox(l, i, {
        active: isActive,
        dest: isDest,
        comparePos: compareMap[k],
        outputPos: outputMap[k],
        bad: badMap[k]
      }, frame);
    }
  }
  drawStaticLabels();
}

function setMergeCallTrace(v) {
  replayMode = false;
  stopPlay();
  callTrace = v;
  renderCurrent();
}

function toggle_stableMergeTrace(on) {
  stableTrace = !!on;
  renderCurrent();
}

function toggleWorkbench() {
  workbenchOpen = !workbenchOpen;
  document.getElementById('workbench').style.display = workbenchOpen ? 'inline' : 'none';
  document.getElementById('workbenchToggle').textContent = workbenchOpen ? 'Hide coding workbench' : 'Show coding workbench';
  if (window.__autoUiLayout) setTimeout(window.__autoUiLayout, 0);
}

function loadCodeSample(which) {
  var t = document.getElementById('mergeRoutineCode');
  t.value = which === 'buggy' ? buggyCode : (which === 'starter' ? starterCode : sampleCode);
}

function workerSource() {
  return `
self.onmessage = function(ev) {
  var code = ev.data.code, input = ev.data.input;
  var frames = [], opCount = 0, frameCap = 650, opCap = 420;
  function cp(x){ return JSON.parse(JSON.stringify(x)); }
  function elem(v,i){ return {v:v,id:i}; }
  function parseInput(s){
    var parts = String(s).split(',').map(function(x){ return x.trim(); }).filter(Boolean);
    if (parts.length !== 8) throw new Error('Use exactly 8 comma-separated numbers for this lattice.');
    return parts.map(function(p,i){ var n = Number(p); if(!isFinite(n)) throw new Error('Not a number: '+p); return elem(n,i); });
  }
  var initial, levels, runs, active, leftRun, rightRun, out, li, ri;
  function snapshot(kind, indices, message){
    opCount++;
    if (opCount > opCap) throw new Error('operation cap hit; check for an infinite loop');
    if (frames.length >= frameCap) throw new Error('frame cap hit; the trace is too long');
    frames.push({kind:kind, state:{levels:cp(levels)}, active:cp(active), indices:cp(indices||{}), message:String(message||'')});
  }
  function hasLeft(){ snapshot('hasLeft',{left:{level:active.left.level,index:active.left.index,pos:li}}, 'hasLeft() → '+(li<leftRun.length)); return li < leftRun.length; }
  function hasRight(){ snapshot('hasRight',{right:{level:active.right.level,index:active.right.index,pos:ri}}, 'hasRight() → '+(ri<rightRun.length)); return ri < rightRun.length; }
  function compareFront(){
    if (li >= leftRun.length || ri >= rightRun.length) throw new Error('compareFront() called when one run is empty');
    var a = leftRun[li], b = rightRun[ri], c = a.v < b.v ? -1 : (a.v > b.v ? 1 : 0);
    snapshot('compare', {
      left:{level:active.left.level,index:active.left.index,pos:li},
      right:{level:active.right.level,index:active.right.index,pos:ri}
    }, 'compareFront(): '+a.v+' vs '+b.v+' → '+c);
    return c;
  }
  function appendLeft(){
    if (li >= leftRun.length) throw new Error('appendLeft() called with no left front element');
    out.push({v:leftRun[li].v,id:leftRun[li].id}); li++;
    levels[active.level][active.dest] = cp(out);
    snapshot('appendLeft', {output:{level:active.level,index:active.dest,pos:out.length-1}}, 'appendLeft(): output now ['+out.map(function(e){return e.v}).join(', ')+']');
  }
  function appendRight(){
    if (ri >= rightRun.length) throw new Error('appendRight() called with no right front element');
    out.push({v:rightRun[ri].v,id:rightRun[ri].id}); ri++;
    levels[active.level][active.dest] = cp(out);
    snapshot('appendRight', {output:{level:active.level,index:active.dest,pos:out.length-1}}, 'appendRight(): output now ['+out.map(function(e){return e.v}).join(', ')+']');
  }
  function note(text){ snapshot('note', {}, String(text)); }
  var api = Object.freeze({hasLeft:hasLeft, hasRight:hasRight, compareFront:compareFront, appendLeft:appendLeft, appendRight:appendRight, note:note});
  try {
    initial = parseInput(input);
    levels = [initial.map(function(e){return [e];}), [], [], []];
    runs = levels[0].map(cp);
    frames.push({kind:'start', state:{levels:cp(levels)}, active:null, indices:{}, message:'Start with eight single-element sorted runs.'});
    var factory = new Function('hasLeft','hasRight','compareFront','appendLeft','appendRight','note', code + '\\n; return (typeof merge === "function") ? merge : null;');
    var mergeFn = factory(api.hasLeft, api.hasRight, api.compareFront, api.appendLeft, api.appendRight, api.note);
    if (!mergeFn) throw new Error('Define the required entry point: function merge(left, right) { ... }');
    for (var lev=1; runs.length > 1; lev++) {
      var next = [];
      levels[lev] = [];
      for (var p=0; p<runs.length; p+=2) {
        leftRun = cp(runs[p]); rightRun = cp(runs[p+1]); out = []; li = 0; ri = 0;
        active = {level:lev,dest:p/2,left:{level:lev-1,index:p},right:{level:lev-1,index:p+1}};
        levels[lev][p/2] = [];
        snapshot('activate', {}, 'Merge ['+leftRun.map(function(e){return e.v}).join(', ')+'] with ['+rightRun.map(function(e){return e.v}).join(', ')+']');
        mergeFn(Object.freeze(leftRun.map(function(e){return e.v;})), Object.freeze(rightRun.map(function(e){return e.v;})));
        levels[lev][p/2] = cp(out);
        next.push(cp(out));
      }
      runs = next;
    }
    var final = runs[0] || [];
    var bad = [];
    for (var i=1;i<final.length;i++) {
      if (final[i-1].v > final[i].v || (final[i-1].v === final[i].v && final[i-1].id > final[i].id)) bad.push(i-1,i);
    }
    var ids = final.map(function(e){return e.id}).sort(function(a,b){return a-b}).join(',');
    var expectedIds = initial.map(function(e){return e.id}).sort(function(a,b){return a-b}).join(',');
    var okSet = ids === expectedIds;
    var ok = bad.length === 0 && okSet && final.length === initial.length;
    frames.push({kind: ok?'correct':'wrong', state:{levels:cp(levels)}, active:{level:3,dest:0}, indices: ok?{}:{bad:[{level:3,index:0}]}, message: ok ? 'Correct: outputs are sorted and stable; equal values keep left-before-right order.' : 'Wrong answer: the final run is not sorted, stable, or does not contain exactly the input elements.', status: ok?'correct':'wrong'});
    self.postMessage({ok:true, frames:frames, status: ok?'correct':'wrong'});
  } catch(e) {
    frames.push({kind:'error', state:{levels:cp(levels || [[]])}, active:active ? cp(active) : null, indices:{}, message:'Error: '+(e && e.message ? e.message : e), status:'error'});
    self.postMessage({ok:false, frames:frames, status:'error', error:String(e && e.message ? e.message : e)});
  }
};`;
}

function runMergeRoutine() {
  if (!workbenchOpen) toggleWorkbench();
  stopPlay();
  var btn = document.getElementById('runMergeBtn');
  btn.disabled = true;
  document.getElementById('mergeStatus').textContent = 'running…';
  var blob = new Blob([workerSource()], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var w = new Worker(url);
  var finished = false;
  var timer = setTimeout(function () {
    if (finished) return;
    finished = true;
    w.terminate();
    URL.revokeObjectURL(url);
    btn.disabled = false;
    traceFrames = [{ kind: 'timeout', state: { levels: cp(canonical) }, active: null, indices: {}, message: 'Error: time limit hit; check for an infinite loop.', status: 'error' }];
    frameIndex = 0;
    replayMode = true;
    document.getElementById('mergeStatus').textContent = 'error';
    renderCurrent();
  }, 1800);
  w.onmessage = function (ev) {
    if (finished) return;
    finished = true;
    clearTimeout(timer);
    w.terminate();
    URL.revokeObjectURL(url);
    btn.disabled = false;
    traceFrames = ev.data.frames || [];
    frameIndex = 0;
    replayMode = true;
    document.getElementById('mergeStatus').textContent = ev.data.status === 'correct' ? 'correct' : (ev.data.status === 'wrong' ? 'wrong answer' : 'error');
    renderCurrent();
  };
  w.postMessage({ code: document.getElementById('mergeRoutineCode').value, input: document.getElementById('mergeRoutineInput').value });
}

function renderCurrent() {
  var f = replayMode ? traceFrames[frameIndex] : null;
  renderFigure(f);
  var counter = document.getElementById('frameCounter');
  var caption = document.getElementById('frameCaption');
  var log = document.getElementById('traceLog');
  if (counter) counter.textContent = traceFrames.length ? ((frameIndex + 1) + ' of ' + traceFrames.length) : '0 of 0';
  if (caption) caption.textContent = f ? f.message : 'Use the call-trace menu or run your merge routine.';
  if (log) log.value = traceFrames.map(function (fr, i) { return (i + 1) + '. ' + fr.message; }).join('\n');
}

function firstFrame() { if (!traceFrames.length) return; replayMode = true; frameIndex = 0; renderCurrent(); }
function prevFrame() { if (!traceFrames.length) return; replayMode = true; frameIndex = Math.max(0, frameIndex - 1); renderCurrent(); }
function nextFrame() { if (!traceFrames.length) return; replayMode = true; frameIndex = Math.min(traceFrames.length - 1, frameIndex + 1); renderCurrent(); }
function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  var p = document.getElementById('playBtn');
  if (p) p.textContent = '▶';
}
function togglePlay() {
  if (!traceFrames.length) return;
  if (playTimer) { stopPlay(); return; }
  replayMode = true;
  document.getElementById('playBtn').textContent = '❚❚';
  var speed = +document.getElementById('speedInput').value || 4;
  playTimer = setInterval(function () {
    if (frameIndex >= traceFrames.length - 1) { stopPlay(); return; }
    frameIndex++;
    renderCurrent();
  }, Math.max(120, 950 - speed * 95));
}

function applyDemoStep() {
  var st = demoSteps[demoIndex];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
  document.getElementById('mergeCallTraceInput').value = st.state.mergeCallTrace;
  document.getElementById('stableMergeTraceInput').checked = st.state.stableMergeTrace === 'Show duplicate origins';
  callTrace = st.state.mergeCallTrace;
  stableTrace = st.state.stableMergeTrace === 'Show duplicate origins';
  replayMode = false;
  stopPlay();
  renderCurrent();
}
function prevStep() { demoIndex = Math.max(0, demoIndex - 1); applyDemoStep(); }
function nextStep() { demoIndex = Math.min(demoSteps.length - 1, demoIndex + 1); applyDemoStep(); }

renderFigure(null);
applyDemoStep();
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original static 2D figure, making a generation plan, generating an interactive 2D figure (SVG.js / Chart.js / Mermaid), and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

Example 1 → pass
